 if i==45 or i==95 or (i>45 and (c[i-1,1]-generate.GROUND_CENTER_Y)*(c[i,1]-generate.GROUND_CENTER_Y)<=0) or i%3==0:
  print(i, np.round(c[i],2), 'height',round(generate.GROUND_CENTER_Y-c[i,1],2))
# local minima/maxima in y
for i in range(46,95):
 if (c[i,1]-c[i-1,1])*(c[i+1,1]-c[i,1])<=0:
  print('turn',i,np.round(c[i],2))
